function CareTaskBoard() {
  const [query, setQuery] = useState('')
  const [done, setDone] = useState<string[]>([])
  const visible = clinicalTasks.filter(task => `${task.task} ${task.patient}`.toLowerCase().includes(query.toLowerCase()))
  return <section className="care-task-board">
    <header><div><p className="eyebrow">Clinical task queue</p><h2>Work that needs a decision</h2><p>Patient-linked actions gathered from visits, shared notes, and follow-up plans.</p></div><label className="task-search"><Search/><span className="sr-only">Search clinical tasks</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search tasks"/></label></header>
    <div className="task-ledger"><div className="task-row task-head"><span/><span>Task</span><span>Patient</span><span>Due</span><span>Priority</span><span/></div>{visible.map(task => <div className={`task-row ${done.includes(task.id) ? 'is-done' : ''}`} key={task.id}><button className="task-check" onClick={() => setDone(current => current.includes(task.id) ? current.filter(id => id !== task.id) : [...current, task.id])} aria-label={`${done.includes(task.id) ? 'Reopen' : 'Complete'} ${task.task}`}>{done.includes(task.id) && <Check/>}</button><span><strong>{task.task}</strong><small>{task.id}</small></span><span>{task.patient}</span><time>{task.due}</time><Status value={task.priority}/><button className="icon-button" aria-label={`More actions for ${task.task}`}><MoreHorizontal/></button></div>)}</div>
    {!visible.length && <div className="task-empty"><ClipboardCheck/><strong>No matching tasks</strong><span>Change the search to see the rest of your clinical queue.</span></div>}
  </section>
}

function DoctorDirectory({ onBook }: { onBook: (doctor: Doctor) => void }) {
  const { doctors } = useDemoData()
  const [query, setQuery] = useState('')
  const [specialty, setSpecialty] = useState('All specialties')
  const filtered = doctors.filter(d => (specialty === 'All specialties' || d.specialty === specialty) && `${d.name} ${d.specialty}`.toLowerCase().includes(query.toLowerCase()))
  const specialties = ['All specialties', ...new Set(doctors.map(d => d.specialty))]
  return <div className="page">
    <PageIntro eyebrow="Care network · 48 clinicians" title="Find the right specialist." copy="Search the Sahha network by clinical focus and next availability." />
    <div className="directory-tools"><label className="search-field"><Search /><span className="sr-only">Search doctors</span><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search name or specialty" /></label><div className="filter-row"><SlidersHorizontal size={17} />{specialties.map(s => <button aria-pressed={specialty===s} className={specialty === s ? 'active' : ''} onClick={() => setSpecialty(s)} key={s}>{s}</button>)}</div></div>
    <div className="doctor-grid">{filtered.map((doctor, i) => <article className="doctor-card" key={doctor.id}>
      <div className="doctor-card__index">0{i + 1}</div><div className="doctor-portrait" style={{ '--doctor-tone': doctor.accent } as React.CSSProperties}><span>{doctor.initials}</span><i /></div>
      <div className="doctor-card__body"><p className="eyebrow">{doctor.specialty}</p><h2>{doctor.name}</h2><div className="doctor-meta"><span><Star size={14} fill="currentColor" />{doctor.rating}</span><span>{doctor.experience} years</span></div><p><MapPin size={15} />{doctor.location}</p><div className="language-row">{doctor.languages.map(l => <span key={l}>{l}</span>)}</div></div>
      <div className="doctor-card__footer"><div><span>Next available</span><strong>{doctor.next}</strong></div><button className="primary" onClick={() => onBook(doctor)}>Request visit <ChevronRight size={17} /></button></div>
    </article>)}</div>
    {!filtered.length && <div className="empty-state"><Search /><h2>No exact match</h2><p>Try a different name or broaden the specialty filter.</p></div>}
  </div>
}

