function PlatformSupport(){
  const {recordAudit}=useDemoData()
  const [active,setActive]=useState('SUP-2048')
  const [resolved,setResolved]=useState<string[]>([])
  const [note,setNote]=useState('')
  const [notes,setNotes]=useState<Record<string,string>>(()=>{try{return JSON.parse(localStorage.getItem('aegis-support-notes')||'{}')}catch{return {}}})
  const [filter,setFilter]=useState<'Open'|'Mine'|'Waiting'>('Open')
  const [notice,setNotice]=useState('')
  const tickets=[
    {id:'SUP-2048',subject:'Cannot access appointment summary',person:'Nora Bennett',role:'Patient',priority:'High',age:'18 min',body:'The appointment appears in history, but the visit summary opens a blank state.'},
    {id:'SUP-2044',subject:'Organization invite expired',person:'Sidi Bou Care Studio',role:'Organization',priority:'Review',age:'42 min',body:'The onboarding administrator needs a fresh invitation and confirmation of the assigned region.'},
    {id:'SAFE-881',subject:'Potentially unsafe review claim',person:'Automated detection',role:'Trust and safety',priority:'High',age:'1 h',body:'A patient review may contain a medication recommendation that should be reviewed before publication.'},
    {id:'SUP-2037',subject:'Duplicate notification delivery',person:'Dr. Elias Chen',role:'Doctor',priority:'Normal',age:'2 h',body:'The same appointment reminder was delivered twice to the clinician workspace.'},
  ]
  const ticket=tickets.find(item=>item.id===active)!
  const visibleTickets=tickets.filter((item,index)=>filter==='Open'?!resolved.includes(item.id):filter==='Mine'?index<2:index>=2)
  const saveNote=()=>{if(note.trim().length<4){setNotice('Add a useful note before saving.');return}const next={...notes,[ticket.id]:note.trim()};setNotes(next);localStorage.setItem('aegis-support-notes',JSON.stringify(next));recordAudit({user:'Avery Kim',action:'Saved support note',target:ticket.id,area:'Operations',result:'Logged'});setNotice(`Internal note saved for ${ticket.id}.`)}
  const resolve=()=>{setResolved(current=>[...current,ticket.id]);recordAudit({user:'Avery Kim',action:'Resolved support ticket',target:ticket.id,area:'Operations',result:'Complete'});setNotice(`${ticket.id} was resolved.`)}
  return <div className="page platform-depth-page support-page">
    <PageIntro eyebrow="Support and safety · 4 open" title="Resolve friction with context." copy="Triage product support, account access, organization onboarding, and safety reports without granting support agents unrestricted clinical access."/>
    <div className="support-layout">
      <section className="support-queue"><div className="support-filters">{(['Open','Mine','Waiting'] as const).map(value=><button aria-pressed={filter===value} className={filter===value?'active':''} onClick={()=>setFilter(value)} key={value}>{value} {value==='Open'?tickets.length-resolved.length:value==='Mine'?2:2}</button>)}</div>{visibleTickets.map(item=><button className={active===item.id?'active':''} onClick={()=>{setActive(item.id);setNote(notes[item.id]||'');setNotice('')}} key={item.id}><span><strong>{item.id}</strong><small>{item.age}</small></span><h2>{item.subject}</h2><p>{item.person} · {item.role}</p><Status value={resolved.includes(item.id)?'Resolved':item.priority}/></button>)}</section>
      <article className="support-detail"><header><div><p className="eyebrow">{ticket.id} · {ticket.role}</p><h1>{ticket.subject}</h1><span>Submitted by {ticket.person} · {ticket.age} ago</span></div><Status value={resolved.includes(ticket.id)?'Resolved':ticket.priority}/></header>{notice&&<p className={notice.includes('Add')?'form-message form-message--error':'form-message form-message--success'} role="status">{notice}</p>}<section className="support-message"><Avatar initials={ticket.person.split(' ').map(value=>value[0]).join('').slice(0,2)} small/><div><strong>{ticket.person}</strong><p>{ticket.body}</p></div></section><div className="support-boundary"><LockKeyhole/><span><strong>Minimum necessary access</strong><small>This support view exposes account and workflow metadata only. Clinical records require a separate, audited authorization path.</small></span></div><label className="support-reply"><span>Internal note or response</span><textarea rows={6} value={note} onChange={event=>setNote(event.target.value)} placeholder="Document what was checked and the next action"/></label><footer><button className="secondary" onClick={saveNote}>Save internal note</button><button disabled={resolved.includes(ticket.id)} className="primary" onClick={resolve}>{resolved.includes(ticket.id)?<><Check/>Resolved</>:<>Resolve ticket</>}</button></footer></article>
    </div>
  </div>
}

