function PlatformAudit(){
  const [query,setQuery]=useState('')
  const [area,setArea]=useState('All')
  const events=[
    {time:'14:42:11',actor:'Avery Kim',organization:'Sahha platform',action:'Updated feature rollout',target:'automated-review-screening',area:'Configuration',result:'Logged'},
    {time:'14:31:08',actor:'System',organization:'14 organizations',action:'Opened platform incident',target:'INC-P14',area:'Reliability',result:'Complete'},
    {time:'14:12:39',actor:'Leila Mansour',organization:'St. Helena Medical',action:'Exported finance report',target:'June 2026',area:'Data export',result:'Logged'},
    {time:'13:58:02',actor:'Avery Kim',organization:'Sahha platform',action:'Approved doctor identity',target:'Dr. Sanaa Idris',area:'Trust',result:'Complete'},
    {time:'13:41:26',actor:'Unknown session',organization:'Carthage Family Clinic',action:'Attempted privileged route',target:'Organization settings',area:'Security',result:'Denied'},
  ]
  const filtered=events.filter(event=>(area==='All'||event.area===area)&&`${event.actor} ${event.organization} ${event.action} ${event.target}`.toLowerCase().includes(query.toLowerCase()))
  return <div className="page platform-depth-page">
    <PageIntro eyebrow="Platform governance · Append-only view" title="Global audit trail." copy="Trace administrative, organization, trust, export, configuration, and security events across the platform. Production retention and immutability belong in the backend audit service." action={<button className="secondary soft"><Download/>Export audit package</button>}/>
    <div className="audit-controls"><label className="search-field"><Search/><span className="sr-only">Search global audit events</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search actor, organization, action, or target"/></label><div className="filter-row"><Filter/>{['All','Configuration','Reliability','Data export','Trust','Security'].map(value=><button aria-pressed={area===value} className={area===value?'active':''} onClick={()=>setArea(value)} key={value}>{value}</button>)}</div></div>
    <section className="platform-audit"><header><span>Time</span><span>Actor</span><span>Organization</span><span>Action</span><span>Target</span><span>Area</span><span>Result</span></header>{filtered.map(event=><article key={`${event.time}-${event.action}`}><time>{event.time}</time><strong>{event.actor}</strong><span>{event.organization}</span><span>{event.action}</span><span>{event.target}</span><span>{event.area}</span><Status value={event.result}/></article>)}{!filtered.length&&<div className="audit-empty"><FileSearch/><strong>No matching events</strong><span>Change the search or event area.</span></div>}</section>
    <p className="audit-retention"><ShieldCheck/>The frontend does not claim immutability. Connect this surface to an append-only backend audit store with retention and export controls.</p>
  </div>
}

