    <section className="org-shift"><div className="panel-heading"><div><p className="eyebrow">Current shift</p><h2>Clinical coverage</h2></div><button className="secondary soft" onClick={()=>navigate('staffing')}>Manage staffing</button></div><div>{organizationClinicians.slice(0,4).map(([name,dept,state,load,next])=><article key={name}><Avatar initials={name.split(' ').slice(-2).map(x=>x[0]).join('')} small/><span><strong>{name}</strong><small>{dept}</small></span><Status value={state}/><span><small>Current load</small><strong>{load}</strong></span><span><small>Next change</small><strong>{next}</strong></span></article>)}</div></section>
