function DepartmentBoard(){const [query,setQuery]=useState('');const visible=departments.filter(d=>d.name.toLowerCase().includes(query.toLowerCase()));return <div className="page organization-page"><PageIntro eyebrow="Clinical structure" title="Departments and service lines." copy="Compare demand, occupancy, clinical coverage, and waiting time without losing department context."/><label className="search-field soft-field"><Search/><span className="sr-only">Search departments</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search departments"/></label><div className="department-grid">{visible.map((dept,index)=><article key={dept.name}><header><span>{String(index+1).padStart(2,'0')}</span><Status value={dept.state}/></header><Hospital/><h2>{dept.name}</h2><p>Led by {dept.lead}</p><dl><div><dt>Patients</dt><dd>{dept.patients}</dd></div><div><dt>Clinicians</dt><dd>{dept.clinicians}</dd></div><div><dt>Wait</dt><dd>{dept.wait}</dd></div></dl><div className="capacity-line"><span>Occupancy</span><strong>{dept.occupancy}%</strong><i><em style={{width:`${dept.occupancy}%`}}/></i></div><button className="text-button">View service line <ArrowUpRight/></button></article>)}</div>{!visible.length&&<div className="empty-state"><Search/><h2>No department found</h2><p>Try another service or department name.</p></div>}</div>}

