function PatientHomeConnected({navigate}:{navigate:(view:PatientView)=>void}){
  const {appointments,doctors,patients}=useDemoData();const [completed,setCompleted]=useState(['Morning medication']);const steps=['Morning medication','Record blood pressure','20-minute walk','Evening medication'];const me=patients[0];const next=appointments.filter(item=>item.patientId===me?.id&&!['COMPLETED','CANCELLED'].includes(item.status)).sort((a,b)=>new Date(a.startsAt).getTime()-new Date(b.startsAt).getTime())[0];const doctor=doctors.find(item=>item.id===next?.doctorId)
  return <div className="page patient-home"><PageIntro eyebrow={`${todayLabel} · Your care`} title={`Good morning, ${me?.name.split(' ')[0]||'there'}.`} copy="Your appointments, treatment plan, recent measurements, and care team are gathered in one calm workspace."/>{next?<div className="patient-hero-grid"><article className="next-visit-card"><p className="eyebrow">Your next appointment</p><div className="visit-date"><strong>{new Date(next.startsAt).getDate()}</strong><span>{new Intl.DateTimeFormat('en',{month:'short'}).format(new Date(next.startsAt)).toUpperCase()}<small>{appointmentTime(next.startsAt)}</small></span></div><h2>{next.reason}</h2><p>{appointmentMode(next.mode)} consultation with {doctor?.name||'your care team'}</p><div><button className="primary soft" disabled title="Video links become active on the visit day"><Video/>Join on visit day</button><button className="secondary soft" onClick={()=>navigate('visits')}>View details</button></div></article><article className="wellbeing-orb"><div className="soft-pulse"><HeartPulse/></div><p>Care plan progress</p><strong>{Math.round(completed.length/steps.length*100)}%</strong><span>{completed.length} of {steps.length} weekly goals complete</span></article></div>:<div className="task-empty"><CalendarDays/><strong>No upcoming visit</strong><button className="primary soft" onClick={()=>navigate('care')}>Find a doctor</button></div>}<div className="soft-metrics"><button onClick={()=>navigate('history')}><Activity/><span><small>Latest blood pressure</small><strong>{me?.vitals[0]?.value||'Not recorded'}</strong><em>{me?.vitals[0]?'Review in your history':'Add at your next visit'}</em></span><ChevronRight/></button><button onClick={()=>navigate('medications')}><FileHeart/><span><small>Active medications</small><strong>{String(me?.medications.length||0).padStart(2,'0')}</strong><em>Review doses and refills</em></span><ChevronRight/></button><button onClick={()=>navigate('care')}><Stethoscope/><span><small>Care network</small><strong>{String(doctors.length).padStart(2,'0')}</strong><em>Find another specialist</em></span><ChevronRight/></button></div><section className="personal-care-list"><header><p className="eyebrow">Your plan this week</p><h2>Small steps, clearly tracked.</h2><p>Keep the routine visible without turning care into a wall of reminders.</p><span>{completed.length} of {steps.length} complete</span></header><div>{steps.map(step=><button className={completed.includes(step)?'complete':''} onClick={()=>setCompleted(current=>current.includes(step)?current.filter(item=>item!==step):[...current,step])} key={step}><i>{completed.includes(step)&&<Check/>}</i><span>{step}</span><ChevronRight/></button>)}</div></section><section className="recommended-care"><div className="panel-heading"><div><p className="eyebrow">Recommended for you</p><h2>Doctors who understand the full picture</h2></div><button className="text-button" onClick={()=>navigate('care')}>Explore all <ArrowUpRight/></button></div><div className="patient-doctor-row">{doctors.slice(0,3).map(item=><article key={item.id}><Avatar initials={item.initials} tone={item.accent}/><div><span>{item.specialty}</span><h3>{item.name}</h3><p><Star fill="currentColor"/> {item.rating||'New'} · {item.location}</p></div><button aria-label={`View ${item.name}`} onClick={()=>navigate('care')}><ArrowUpRight/></button></article>)}</div></section></div>
}

function DoctorAvailabilityConnected(){
  const [days,setDays]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('aegis-doctor-availability')||'null')?.days||['Monday','Tuesday','Wednesday','Thursday']}catch{return ['Monday','Tuesday','Wednesday','Thursday']}});const [times,setTimes]=useState<Record<string,{start:string;end:string}>>(()=>Object.fromEntries(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(day=>[day,{start:'09:00',end:'16:30'}])));const [notice,setNotice]=useState('')
  const toggle=(day:string)=>setDays(current=>current.includes(day)?current.filter(value=>value!==day):[...current,day]);const publish=()=>{localStorage.setItem('aegis-doctor-availability',JSON.stringify({days,times,publishedAt:new Date().toISOString()}));setNotice('Availability published to the demo booking calendar.')}
  return <div className="page doctor-work-page"><PageIntro eyebrow="Practice schedule" title="Availability that protects clinical focus." copy="Define consultation windows and publish the weekly pattern patients will see when they request a visit." action={<button className="primary" onClick={publish}><Check/>Publish schedule</button>}/>{notice&&<div className="inline-success" role="status"><Check/>{notice}</div>}<div className="availability-layout"><section><header><p className="eyebrow">Weekly pattern</p><h2>Consultation hours</h2></header>{Object.keys(times).map(day=><article className={days.includes(day)?'enabled':''} key={day}><button role="switch" aria-label={`${day} availability`} aria-checked={days.includes(day)} onClick={()=>toggle(day)}><i/></button><strong>{day}</strong>{days.includes(day)?<><label><span className="sr-only">{day} start time</span><input type="time" value={times[day].start} onChange={event=>setTimes(current=>({...current,[day]:{...current[day],start:event.target.value}}))}/></label><span>to</span><label><span className="sr-only">{day} end time</span><input type="time" value={times[day].end} onChange={event=>setTimes(current=>({...current,[day]:{...current[day],end:event.target.value}}))}/></label></>:<span className="day-off">Not available</span>}</article>)}</section><aside><p className="eyebrow">Booking rules</p>{[['Appointment length','30 minutes'],['Minimum lead time','12 hours'],['Booking horizon','60 days'],['Video consultations','Enabled'],['Urgent visit buffer','15 minutes']].map(([label,value])=><div className="booking-rule" key={label}><span><strong>{label}</strong><small>{value}</small></span><Check/></div>)}<div className="schedule-preview"><CalendarDays/><span><strong>{days.length*7} hours available</strong><small>{days.length*14} appointment slots in a full week</small></span></div></aside></div></div>
}

function PatientMessagesConnected(){
  const {messages,sendMessage}=useDemoData();const [active,setActive]=useState(101);const [draft,setDraft]=useState('');const threads=[{id:101,name:'Cardiology care team',initials:'CV',category:'Clinical',response:'Usually replies within one business day',messages:[{from:'them',text:'Your blood pressure readings have been reviewed. Please continue recording them through Tuesday.',time:'Yesterday · 14:26'}]},{id:102,name:'Patient services',initials:'PS',category:'Administrative',response:'Usually replies within four hours',messages:[{from:'them',text:'Your insurance information has been updated for the July appointment.',time:'Yesterday · 09:12'}]}];const thread=threads.find(item=>item.id===active)!
  const send=()=>{if(!draft.trim())return;sendMessage(active,draft.trim());setDraft('')}
  return <div className="page patient-detail-page"><PageIntro eyebrow="Private demo messages · 2 threads" title="A clear line to your care team." copy="Use clinical threads for care questions and patient services for appointments, registration, or insurance."/><div className="patient-messenger"><aside><div className="message-guidance"><ShieldCheck/><span><strong>Not for emergencies</strong><small>Call local emergency services for urgent or life-threatening symptoms.</small></span></div>{threads.map(item=><button className={active===item.id?'active':''} onClick={()=>setActive(item.id)} key={item.id}><Avatar initials={item.initials} small/><span><strong>{item.name}</strong><small>{item.category} · {item.response}</small></span><ChevronRight/></button>)}</aside><section><header><Avatar initials={thread.initials}/><span><h2>{thread.name}</h2><p>{thread.response}</p></span></header><div className="patient-message-stream">{[...thread.messages,...(messages[active]||[])].map((message,index)=><article className={message.from==='me'?'mine':''} key={`${message.time}-${index}`}><p>{message.text}</p><time>{message.time}</time></article>)}</div><form onSubmit={event=>{event.preventDefault();send()}}><button type="button" className="icon-button" disabled aria-label="Attachments unavailable in the demo"><Paperclip/></button><label><span className="sr-only">Message</span><textarea value={draft} onChange={event=>setDraft(event.target.value)} rows={2} placeholder={`Message ${thread.name}`}/></label><button disabled={!draft.trim()} className="send-button" aria-label="Send message"><Send/></button></form></section></div></div>
}

function DoctorEncounterConnected({patient,complete,navigate}:{patient:Patient;complete:()=>void;navigate:(view:View)=>void}){
  const blank={subjective:'',objective:'',assessment:'',plan:''};const [section,setSection]=useState<keyof typeof blank>('subjective');const [note,setNote]=useState<typeof blank>(()=>{try{return JSON.parse(localStorage.getItem(`aegis-encounter-draft-${patient.id}`)||'null')||blank}catch{return blank}});const [saveState,setSaveState]=useState('Draft ready');const [signed,setSigned]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{setSaveState('Saving draft…');const timeout=window.setTimeout(()=>{localStorage.setItem(`aegis-encounter-draft-${patient.id}`,JSON.stringify(note));setSaveState('Draft autosaved')},500);return()=>window.clearTimeout(timeout)},[note,patient.id])
  const sign=()=>{if(Object.values(note).some(value=>value.trim().length<8)){setError('Complete every clinical note section before signing.');return}localStorage.setItem(`aegis-encounter-${patient.id}`,JSON.stringify({...note,signedAt:new Date().toISOString()}));setSigned(true);setSaveState('Signed and locked')}
  return <div className="page encounter-page"><button className="back-button" onClick={complete}><ArrowLeft/>Back to patient record</button><div className="encounter-header"><div className="record-person"><Avatar initials={patient.initials}/><div><p className="eyebrow">Active encounter · {patient.id}</p><h1>{patient.name}</h1><p>{patient.age} years · {patient.condition} · Clinical documentation</p></div></div><span aria-live="polite"><i/>{saveState}</span></div><div className="encounter-layout"><aside><p className="eyebrow">Clinical note</p>{(Object.keys(blank) as Array<keyof typeof blank>).map(key=><button className={section===key?'active':''} onClick={()=>setSection(key)} key={key}><span>{key[0].toUpperCase()+key.slice(1)}</span>{note[key].length>7?<Check/>:<i/>}</button>)}<div className="encounter-safety"><ShieldAlert/><span><strong>Allergy</strong><small>{patient.allergies.join(', ')}</small></span></div></aside><section className="note-editor"><header><div><p className="eyebrow">{section}</p><h2>{section[0].toUpperCase()+section.slice(1)} note</h2></div><span>{note[section].length} characters</span></header><textarea autoFocus value={note[section]} onChange={event=>{setNote((current:typeof blank)=>({...current,[section]:event.target.value}));setError('')}} placeholder="Document the relevant clinical information for this section."/><div className="note-context"><span>Clinical snapshot</span>{patient.vitals.slice(0,3).map(vital=><div key={vital.label}><small>{vital.label}</small><strong>{vital.value}</strong></div>)}</div>{error&&<p className="encounter-error" role="alert">{error}</p>}<footer><button className="secondary" onClick={()=>{localStorage.setItem(`aegis-encounter-draft-${patient.id}`,JSON.stringify(note));setSaveState('Draft saved')}}>Save now</button><button disabled={signed} className="primary" onClick={sign}>{signed?<><Check/>Signed and locked</>:<><ClipboardCheck/>Sign encounter</>}</button></footer></section><aside className="encounter-actions"><p className="eyebrow">During this visit</p><button onClick={()=>navigate('orders')}><FlaskConical/><span>Order laboratory test</span><ChevronRight/></button><button onClick={()=>navigate('orders')}><Pill/><span>Create prescription</span><ChevronRight/></button><button onClick={()=>navigate('orders')}><ArrowUpRight/><span>Send referral</span><ChevronRight/></button><button onClick={()=>navigate('appointments')}><CalendarDays/><span>Schedule follow-up</span><ChevronRight/></button></aside></div></div>
}

function PatientAppointmentGuide(){return <section className="page page-continuation appointment-guide" aria-labelledby="appointment-guide-title"><header><p className="eyebrow">Before your next visit</p><h2 id="appointment-guide-title">Know what happens next.</h2><p>Appointment status, preparation, and follow-up stay visible so you do not have to guess what the clinic needs.</p></header><div><article><CalendarDays/><span><strong>Requested</strong><small>The clinic reviews availability and your visit reason.</small></span></article><article><Bell/><span><strong>Confirmed</strong><small>Reminders and preparation details arrive before the visit.</small></span></article><article><FileHeart/><span><strong>Follow-up</strong><small>The visit summary and next care actions appear in your history.</small></span></article></div></section>}

export default function App() {
  const navigate=useNavigate(); const auth=useAuth(); const [theme,setTheme]=useState<Theme>(() => { const saved=localStorage.getItem('aegis-theme'); if(saved==='light'||saved==='dark')return saved; return window.matchMedia('(prefers-color-scheme: light)').matches?'light':'dark' })
  useEffect(()=>{ document.documentElement.dataset.theme=theme; localStorage.setItem('aegis-theme',theme) },[theme])
  const toggleTheme=()=>setTheme(t=>t==='dark'?'light':'dark')
  const roleForPortal:Record<Exclude<Portal,'landing'>,string>={patient:'patient',doctor:'doctor',organization:'hospital-operations',admin:'platform-admin'}
  const enter=(portal:Portal)=>navigate(portal==='landing'?'/':`/login?role=${roleForPortal[portal]}`)
  const exit=async()=>{await auth.logout();navigate('/')}
  return <Routes>
    <Route path="/" element={<Landing enter={enter} theme={theme} toggleTheme={toggleTheme}/>}/>
    <Route path="/login" element={<Suspense fallback={<SessionLoading/>}><LoginPage/></Suspense>}/>
    <Route path="/register" element={<Suspense fallback={<SessionLoading/>}><RegisterPage/></Suspense>}/>
    <Route path="/verify-email" element={<Suspense fallback={<SessionLoading/>}><VerifyEmailPage/></Suspense>}/>
    <Route path="/organisations/select" element={<ProtectedRoute><OrganisationSelectionPage/></ProtectedRoute>}/>
    <Route path="/doctor/*" element={<ProtectedRoute roles={['doctor']}><AppShell onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/patient/*" element={<ProtectedRoute roles={['patient']}><PatientPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/hospital/operations/*" element={<ProtectedRoute roles={['hospital-operations']}><OrganizationPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/hospital/admin/*" element={<ProtectedRoute roles={['hospital-super-admin']}><OrganizationPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/reception/*" element={<ProtectedRoute roles={['receptionist']}><OrganizationPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/staff/*" element={<ProtectedRoute roles={['staff']}><StaffPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/platform/*" element={<ProtectedRoute roles={['platform-admin']}><AdminPortal onExit={exit} theme={theme} toggleTheme={toggleTheme}/></ProtectedRoute>}/>
    <Route path="/forbidden" element={<ForbiddenState back={()=>navigate(auth.session?roleHome[auth.session.user.role]:'/login')}/>}/>
    <Route path="/privacy" element={<LegalPage kind="Privacy"/>}/><Route path="/terms" element={<LegalPage kind="Terms"/>}/>
    <Route path="*" element={<NotFound/>}/>
  </Routes>
}
